        } catch (error) { console.error('Chart initialization failed for ' + canvasId + ':', error); return null; }
      },
      destroyAll: function() { this.charts.forEach(function(chart) { chart.destroy(); }); this.charts.clear(); }
    };
    function buildBenchmarkChart() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
      var isDark = document.documentElement.classList.contains('theme-dark');
      var textColor = isDark ? '#eef7fa' : '#102033';
      var gridColor = isDark ? 'rgba(255,255,255,0.06)' : 'rgba(15,37,56,0.07)';
      ChartManager.safeInit('benchmarkChart', {
