            x: { ticks: { color: textColor, font: { size: 22, weight: '600' } }, grid: { display: false } }
          }
        }
      });
      chartsBuilt = true;
    }
    function onThemeChange() { if (chartsBuilt) { chartsBuilt = false; ChartManager.destroyAll(); buildBenchmarkChart(); } }
