(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 2384, height: 3370 }, deviceScaleFactor: 1 });
  await page.goto('file:///app/output/poster.html', { waitUntil: 'networkidle' });
  await page.evaluate(() => {
    localStorage.setItem('viz-theme', 'light');
    document.documentElement.className = 'theme-light';
    const menu = document.querySelector('.viz-menu');
    if (menu) menu.style.display = 'none';
  });
  await page.waitForTimeout(500);
  const poster = await page.$('.poster');
  await poster.screenshot({ path: '/app/output/final_poster.png' });
  await browser.close();
})();
EOF
